function pointBank(p){return p.x<river(p.y)?-1:1;}
function snapBank(p){let side=pointBank(p),y=Math.max(50,Math.min(650,p.y));return {x:river(y)+side*19,y,side};}
function bridgeFor(a,b){return S.bridges.find(x=>x.heads.includes(a.id)&&x.heads.includes(b.id)&&a.id!==b.id);}
function bridgeForHead(id){return S.bridges.find(x=>x.heads.includes(id));}
function bridgeCompatible(x,t){return x.type===physicalGroup(t);}
function validBridgePair(a,b,t){let x=bridgeFor(a,b);return x&&bridgeCompatible(x,t)&&x.status==='open';}
