function bridgeTerrainIssue(a,b){if(!a||!b)return '拖到对岸河岸，桥长不超过260';if(![a.x,a.y,b.x,b.y].every(Number.isFinite))return '桥头位置无效';if(pointBank(a)===pointBank(b))return '请把桥头拖到对岸';if(Math.hypot(a.x-b.x,a.y-b.y)>260)return '桥长不能超过260';if(requirements(a,b,'air').invalid||Math.max(a.x-coast(a.y),b.x-coast(b.y))>=-4)return '桥头不能位于海域';if(mountainCrossings(a,b).length)return '桥位穿入山体，请沿河移动桥头到河谷空地';return null;}
