function routeBridgeStops(stops,type){let result=[],invalid=null;for(let i=0;i<stops.length;i++){let b=S.cities[stops[i]];if(!b||b.removed)continue;if(!result.length){result.push(b.id);continue;}let a=S.cities[result.at(-1)],direct=bridgeFor(a,b);if(direct){if(!bridgeCompatible(direct,type)||direct.status!=='open')invalid='桥梁类型不匹配，或桥梁已停止通行';result.push(b.id);continue;}let r=requirements(a,b,type);if(r.bridge&&type!=='air'){let candidates=S.bridges.filter(x=>x.status==='open'&&bridgeCompatible(x,type)).map(x=>{let h=x.heads.map(id=>S.cities[id]);let start=pointBank(a)===pointBank(h[0])?h[0]:h[1],end=start===h[0]?h[1]:h[0];return {x,start,end,d:Math.hypot(a.x-start.x,a.y-start.y)+Math.hypot(b.x-end.x,b.y-end.y)};}).filter(x=>pointBank(a)!==pointBank(b)&&!requirements(a,x.start,type).bridge&&!requirements(x.end,b,type).bridge).sort((x,y)=>x.d-y.d);let chosen=candidates[0];if(chosen){for(let id of [chosen.start.id,chosen.end.id,b.id])if(result.at(-1)!==id)result.push(id);}else{invalid='跨河前请先在工程采购中手动建桥';result.push(b.id);}}else result.push(b.id);}return {stops:result,invalid};}
const cost02=draftCost;draftCost=function(){if(!draft)return {bridge:0,tunnel:0,cash:0,works:0,vehicle:0};let resolved=routeBridgeStops(draft.stops,draft.type),cost={bridge:0,tunnel:0,cash:0,works:0,vehicle:0,length:0,reused:0,invalid:resolved.invalid,resolved:resolved.stops},seen=new Set();if(resolved.stops.filter(id=>S.cities[id].kind!=='bridgehead').length<2)cost.invalid='线路至少连接两座城市，桥头不算车站';for(let i=1;i<resolved.stops.length;i++){let a=S.cities[resolved.stops[i-1]],b=S.cities[resolved.stops[i]],bridge=bridgeFor(a,b),k=key(a,b,draft.type);if(bridge){cost.reused++;continue;}let req=requirements(a,b,draft.type);if(req.invalid)cost.invalid=req.invalid;if(!S.corridors[k]&&!seen.has(k)){seen.add(k);let length=Math.hypot(a.x-b.x,a.y-b.y);cost.length+=length;cost.tunnel+=req.tunnel||0;if(!draft.stopRemoval)cost.cash+=10*Math.ceil(length*({bus:.38,emu:.65,rail:1.1,air:.18}[draft.type]));}}cost.works=Math.max(0,cost.tunnel-S.inventory.tunnel)*2200;if(!draft.original&&!S.inventory[draft.type])cost.vehicle=TYPES[draft.type].vehicle;cost.cash+=cost.works+cost.vehicle;return cost;};
