function settleClosures(){for(let [k,b] of Object.entries(S.blockages)){if(b.status==='pending'&&!S.vehicles.some(v=>currentEdge(v)===k&&b.allowed.includes(v.id))){b.status='broken';if(b.cause==='demolish'){let bridge=S.bridges.find(x=>x.id===b.bridgeId);if(bridge&&bridge.status!=='removed'){bridge.status='removed';for(let id of bridge.heads)S.cities[id].removed=true;credit(10*Math.floor(bridge.price/10*.25),'subsidy','拆桥回收');toast('桥梁已拆除，相关线路在此断开');}}else toast('受损路段车辆已清空，线路正式断开');}if(b.status==='repairing'&&S.day>=b.until){delete S.blockages[k];toast('路段修复完成，连接已恢复');}}}
