function serves(v,l,index){let {lo,hi,cfg}=serviceRange(v,l),c=S.cities[l.stops[index]];return index>=lo&&index<=hi&&c.kind!=='bridgehead'&&!(cfg.mode==='express'&&(cfg.skip||[]).includes(c.id));}
function departureIndex(v,l){let {lo,hi}=serviceRange(v,l),i=v.index;if(i<lo)return i+1;if(i>hi)return i-1;let dirs=[v.dir,-v.dir];for(let d of dirs){let n=i+d;if(n<lo||n>hi)continue;let a=S.cities[l.stops[i]],b=S.cities[l.stops[n]];if(canEnter(a,b,l.type,v)){v.dir=d;return n;}}return -1;}
plan=function(start,p){let n=S.cities.length,dist=Array(n).fill(Infinity),first=Array(n).fill(null),done=new Set();dist[start]=0;for(let turn=0;turn<n;turn++){let u=-1;for(let i=0;i<n;i++)if(!done.has(i)&&(u<0||dist[i]<dist[u]))u=i;if(u<0||!Number.isFinite(dist[u]))break;done.add(u);if(u!==start&&matchesDestination(S.cities[u],p))return {...first[u],target:u,time:dist[u]};for(let l of S.lines){if(l.retiring||l.type==='air'&&weatherFactor(S.cities[u],'air')===0)continue;let idx=l.stops.indexOf(u);if(idx<0)continue;let groups=new Map();for(let v of S.vehicles.filter(v=>v.line===l.id&&!v.recall)){if(!serves(v,l,idx)||!sameComponent(v,l,idx))continue;let sig=JSON.stringify(v.service||{});if(!groups.has(sig))groups.set(sig,[]);groups.get(sig).push(v);}for(let vs of groups.values()){let v=vs[0],{lo,hi}=serviceRange(v,l),round=0;for(let j=lo+1;j<=hi;j++){let t=serviceTravelTime(v,l,j-1,1);round+=Number.isFinite(t)?t+1:25;}let wait=Math.min(25,round/Math.max(1,vs.length));for(let dir of [-1,1]){let travel=0;for(let j=idx+dir;j>=lo&&j<=hi;j+=dir){let a=S.cities[l.stops[j-dir]],b=S.cities[l.stops[j]];if(!canEnter(a,b,l.type))break;let time=serviceTravelTime(v,l,j-dir,dir);if(!Number.isFinite(time))break;travel+=time;if(serves(v,l,j)){let nd=dist[u]+travel+wait+TYPES[l.type].transfer*(S.cities[u].hub?.7:1);if(nd<dist[b.id]){dist[b.id]=nd;first[b.id]=first[u]||{line:l.id,next:l.stops[idx+dir],vehicleIds:vs.map(x=>x.id)};}break;}}}}}}return null;};
arrival=function(v,l){let live=S.lines.find(x=>x.id===v.line),city=S.cities[l.stops[v.index]];if(!live||!city)return;if(v.stops&&live.stops.includes(city.id)){v.index=live.stops.indexOf(city.id);v.stops=null;l=live;}if(city.kind==='bridgehead'){v.dwell=0;return;}if(v.pendingService||live.retiring||v.recall||serves(v,l,v.index))v.people=v.people.filter(p=>!finishPassengerAtCity(p,city));if(v.pendingService){for(let p of v.people){p.ready=1;city.q.push(p);}v.people=[];v.service=v.pendingService;delete v.pendingService;}
if(live.retiring||v.recall){for(let p of v.people){p.ready=2;city.q.push(p);}v.people=[];retireVehicleAsset(v);return;}if(!serves(v,l,v.index)){v.dwell=0;return;}let nextIdx=departureIndex(v,l),next=nextIdx>=0?l.stops[nextIdx]:null,keep=[];for(let p of v.people){if(finishPassengerAtCity(p,city))continue;let onward=plan(city.id,p);if(next!==null&&onward?.line===l.id&&onward.next===next&&onward.vehicleIds.includes(v.id))keep.push(p);else{p.ready=onward?TYPES[S.lines.find(x=>x.id===onward.line).type].transfer*(city.hub?.7:1):1.5;city.q.push(p);}}v.people=keep;city.q.sort((a,b)=>b.wait-a.wait);let remain=[];for(let p of city.q){if(next===null||p.ready>0||v.people.length>=vehCap(v)){remain.push(p);continue;}let r=plan(city.id,p);if(r?.line===l.id&&r.next===next&&r.vehicleIds.includes(v.id))v.people.push(p);else remain.push(p);}city.q=remain;v.dwell=l.type==='air'?4:isTrain(l.type)?1.7:1;v.dwellMax=v.dwell;};
const baseEdgeTime03=edgeTime;edgeTime=function(a,b,type){let bridge=bridgeFor(a,b),time=baseEdgeTime03(a,b,type);if(bridge){time=Math.hypot(a.x-b.x,a.y-b.y)/TYPES[type].speed/(1+bridge.level*.15);if(bridge.until>S.day)time/=.7;}return time/Math.max(.2,weatherOnEdge(a,b,type));};
tick=function(dt){initializeCityOpeningTimers();let oldDay=Math.floor(S.day);S.day+=dt/12;updateWorld(dt,oldDay);updateClimate(oldDay);for(let bridge of S.bridges)if(bridge.until&&S.day>=bridge.until){bridge.level=bridge.target;delete bridge.until;delete bridge.target;toast('桥面拓宽完工，过桥速度提升');}settleClosures();
for(let c of realCities()){if(c.dormant){if(S.day+1e-9<c.openingAt)continue;activateDiscoveredCity(c,true);}c.grace=Math.max(0,c.grace-dt);c.shield=Math.max(0,c.shield-dt);let longest=0;for(let p of c.q){p.journey=(p.journey||0)+dt;p.ready=Math.max(0,p.ready-dt);if(c.grace<=0&&p.ready<=0)p.wait+=dt;if(!p.eventId)longest=Math.max(longest,p.wait);}updateCongestion(c,dt);if(S.lives<=0){S.paused=true;gameover();return;}c.stage=Math.min(c.size,(c.stage??c.size)+dt/120);if(c.grace<=0){let expected=passengerRate(c)*dt,count=Math.floor(expected)+(Math.random()<expected%1?1:0);for(let i=0;i<count;i++)newPassenger(c);}}
for(let v of S.vehicles){let l=vehicleLine(v);if(!l||v.retired)continue;for(let p of v.people)p.journey=(p.journey||0)+dt;if(v.dwell>0){v.dwell=Math.max(0,v.dwell-dt);continue;}let next=v.t>0?v.index+v.dir:departureIndex(v,l);if(next<0||next>=l.stops.length){v.parked=true;if(S.cities[l.stops[v.index]].kind==='bridgehead'&&v.people.length){let node=S.cities[l.stops[v.index]],safe=realCities().filter(c=>!c.dormant&&(typeof activeAtlasMap!=='undefined'&&activeAtlasMap?!requirements(node,c,'bus').bridge:pointBank(c)===pointBank(node))).sort((a,b)=>Math.hypot(a.x-node.x,a.y-node.y)-Math.hypot(b.x-node.x,b.y-node.y))[0];if(safe){for(let p of v.people){p.ready=2;safe.q.push(p);}v.people=[];}}if(v.recall&&S.cities[l.stops[v.index]].kind!=='bridgehead'){arrival(v,l);}continue;}let a=S.cities[l.stops[v.index]],b=S.cities[l.stops[next]];if(!canEnter(a,b,l.type,v)){v.parked=true;continue;}if(v.t===0&&l.type==='air'&&weatherFactor(a,'air')===0){v.parked=true;continue;}v.parked=false;v.t=advanceVehicleProgress(v,l,a,b,dt);if(v.t>=1){for(let p of v.people)recordSegment(p,a,b,l.type);let pa=lanePoint(a,b,l,.994),pb=lanePoint(a,b,l,1);v.incomingAngle=Math.atan2(pb.y-pa.y,pb.x-pa.x);v.t=0;v.index=next;arrival(v,l);}}
S.vehicles=S.vehicles.filter(v=>!v.retired);S.lines=S.lines.filter(l=>!l.retiring||S.vehicles.some(v=>v.line===l.id));settleClosures();if(S.day>=S.spawnDay){spawnCity();S.spawnDay+=18;}if(Math.floor(S.day/10)>S.periods){S.periods=Math.floor(S.day/10);credit(1000,'subsidy','十天基础补助');S.periodDelivered=0;reward(1000);}S.saveClock+=dt;if(S.saveClock>10){S.saveClock=0;save();}};
function setService(id){let v=S.vehicles.find(v=>v.id===id),l=v&&S.lines.find(l=>l.id===v.line);if(!v||!l)return;let cities=l.stops.filter(id=>S.cities[id].kind!=='bridgehead');openModal(`<div class="modal-head"><h2>${TYPES[v.type].name} #${id} · 运行方案</h2><button class="close" onclick="closeModal()">×</button></div><p>方案在下一座城市交接后生效。区间车集中运力，快车可跳过中间城市；桥头始终正常通过。</p><label>运行模式<select id="service-mode"><option value="all">全程站站停</option><option value="interval">区间站站停</option><option value="express">快车 / 直达</option></select></label><div class="form-row"><label>起点<select id="service-start">${cities.map(id=>`<option value="${id}">${escapeHTML(S.cities[id].name)}</option>`).join('')}</select></label><label>终点<select id="service-end">${cities.map(id=>`<option value="${id}" ${id===cities.at(-1)?'selected':''}>${escapeHTML(S.cities[id].name)}</option>`).join('')}</select></label></div><p>快车跳过的中间城市（起终点始终停靠）</p>${cities.slice(1,-1).map(id=>`<label class="skip-label"><input type="checkbox" class="skip-city" value="${id}">${escapeHTML(S.cities[id].name)}</label>`).join('')}<div class="construction-actions"><button class="primary" onclick="applyService(${v.id})">应用运行方案</button></div>`);}
function applyService(id){let v=S.vehicles.find(v=>v.id===id),l=v&&S.lines.find(l=>l.id===v.line);if(!l)return;let mode=$('service-mode').value,start=+$('service-start').value,end=+$('service-end').value;if(start===end)return toast('运行区间至少需要两座城市');let cfg={mode};if(mode!=='all'){cfg.start=start;cfg.end=end;if(mode==='express')cfg.skip=[...document.querySelectorAll('.skip-city:checked')].map(x=>+x.value).filter(id=>id!==start&&id!==end);}v.pendingService=cfg;closeModal();save();toast('方案将在下一座城市完成交接后生效');}
function repairQuote(k){let ids=k.split('-').slice(-2).map(Number),a=S.cities[ids[0]],b=S.cities[ids[1]];return {price:10*Math.max(40,Math.ceil(Math.hypot(a.x-b.x,a.y-b.y)*.3)),days:3};}
function repairRoad(k){let block=S.blockages[k];if(!block||block.cause==='demolish'||block.status!=='broken')return;let q=repairQuote(k);if(S.points<q.price)return toast('维修需要 ¥'+q.price);spend(q.price,'construction','灾后线路维修');block.status='repairing';block.until=S.day+q.days;save();showEngineering();}
const drawSegment02=drawSegment;drawSegment=function(a,b,l){let x=S.blockages[key(a,b,l.type)];if(x?.status==='broken'||x?.status==='repairing')return;drawSegment02(a,b,l);};
const lineDistance02=displayLineDistance;displayLineDistance=function(p,a,b,l){return S.blockages[key(a,b,l.type)]?.status==='broken'?Infinity:lineDistance02(p,a,b,l);};
const drawInfrastructure02=drawInfrastructure;drawInfrastructure=function(){drawInfrastructure02();for(let [k,b] of Object.entries(S.blockages)){let ids=k.split('-').slice(-2).map(Number),a=S.cities[ids[0]],c=S.cities[ids[1]];if(!a||!c)continue;let x=(a.x+c.x)/2,y=(a.y+c.y)/2;text(b.status==='pending'?'待断开':b.status==='repairing'?'维修中':'× 断线',x,y-8,11,b.status==='pending'?'#c4904d':'#b66050');}};
function weatherCenter(e){let t=Math.max(0,S.day-e.start);return {x:e.x+(e.vx||0)*t,y:e.y+(e.vy||0)*t};}
function stationCoverage(p){return realCities().some(c=>c.meteo&&Math.hypot(c.x-p.x,c.y-p.y)<(c.meteo===1?240:360));}
function weatherFactor(p,type){let factor=1;for(let e of S.climate.events){if(S.day<e.start||S.day>=e.end)continue;let center=weatherCenter(e);if(Math.hypot(p.x-center.x,p.y-center.y)>e.radius)continue;let loss=e.type==='fog'?(type==='bus'?(e.strong?.3:.15):isTrain(type)?(e.strong?.15:.05):(e.strong?.5:.25)):e.type==='rain'?(type==='bus'?(e.strong?.25:.1):isTrain(type)?(e.strong?.15:.05):(e.strong?.35:.12)):(type==='bus'?.45:isTrain(type)?.25:1);if(type==='air'&&e.type==='typhoon')return 0;if(stationCoverage(p))loss*=.5;factor=Math.min(factor,1-loss);}return factor;}
function weatherOnEdge(a,b,type){let n=5,total=0;for(let i=0;i<n;i++){let t=i/(n-1);total+=weatherFactor({x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t},type);}return total/n;}
function updateClimate(oldDay){let cl=S.climate;if(S.day>=cl.next){let cs=realCities().filter(c=>!c.dormant),city=cs[Math.floor(Math.random()*cs.length)]||S.cities[0],month=formatDate().month,typhoon=S.day>=90&&month>=6&&month<=10&&Math.random()<.22;cl.events.push({id:'weather-'+Math.floor(S.day),type:typhoon?'typhoon':Math.random()<.5?'fog':'rain',strong:Math.random()<.4,start:S.day+2,end:S.day+(typhoon?9:6),x:typhoon?1040:city.x+rand(-80,80),y:typhoon?440:city.y+rand(-60,60),radius:typhoon?260:rand(170,260),vx:typhoon?-35:0,vy:typhoon?-4:0});cl.next=S.day+rand(11,18);toast('天气预报已更新 · 工程 / 天气中查看影响范围');}cl.events=cl.events.filter(e=>e.end>S.day);if(Math.floor(S.day)>oldDay&&S.day>=150&&S.unlocked.includes('rail')&&S.day-cl.lastQuake>=80&&realCities().filter(c=>!c.dormant).length>=6&&Math.random()<.008)triggerQuake();}
function triggerQuake(){let candidates=[];for(let l of S.lines){if(l.type==='air')continue;for(let i=1;i<l.stops.length;i++){let a=S.cities[l.stops[i-1]],b=S.cities[l.stops[i]],k=key(a,b,l.type);if(!S.blockages[k]&&!candidates.some(x=>x.k===k))candidates.push({k,a,b});}}if(!candidates.length)return;let center=candidates[Math.floor(Math.random()*candidates.length)],near=candidates.filter(x=>Math.hypot((x.a.x+x.b.x-center.a.x-center.b.x)/2,(x.a.y+x.b.y-center.a.y-center.b.y)/2)<180),count=Math.min(near.length,1+Math.floor(Math.random()*3));for(let x of near.slice(0,count))requestClosure(x.k,'quake');S.climate.lastQuake=S.day;credit(800,'subsidy','地震应急修复补助');toast('局部地震 · '+count+'个路段受损，已有车辆通过后断线 · 应急补助 ¥800');save();}
function drawClimate(){if(meteoPreview){let c=S.cities[meteoPreview.id];ctx.save();ctx.strokeStyle='#7cabb299';ctx.fillStyle='#98bdc011';ctx.setLineDash([5,5]);ctx.beginPath();ctx.arc(c.x,c.y,meteoPreview.radius,0,Math.PI*2);ctx.fill();ctx.stroke();text('气象站覆盖预览',c.x,c.y-meteoPreview.radius+16,10,'#6e99a3');ctx.restore();}for(let e of S.climate.events){let p=weatherCenter(e),forecast=S.day<e.start;ctx.save();ctx.globalAlpha=forecast?.35:.65;ctx.fillStyle=e.type==='fog'?'#d9e0e633':e.type==='rain'?'#b6d1db26':'#abc4cb36';ctx.strokeStyle=forecast?'#abb8b488':'#91adb76b';ctx.lineWidth=1;ctx.setLineDash(forecast?[6,6]:[]);ctx.beginPath();ctx.ellipse(p.x,p.y,e.radius,e.radius*.75,0,0,Math.PI*2);ctx.fill();ctx.stroke();text((forecast?'预报 ':'')+({fog:'雾',rain:'雨',typhoon:'台风'}[e.type])+(e.strong?' · 强':''),p.x,p.y-e.radius*.7,11,'#799aa2');if(!forecast&&e.type==='rain'){ctx.strokeStyle='#8eb0bf66';ctx.setLineDash([]);for(let i=0;i<35;i++){let x=p.x+Math.sin(i*71)*e.radius*.8,y=p.y+Math.cos(i*49)*e.radius*.6;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-2,y+6);ctx.stroke();}}ctx.restore();}for(let c of realCities()){if(!c.meteo)continue;text('⌁',c.x-32,c.y-24,18,'#628c9b');if(selected?.type==='city'&&selected.id===c.id){ctx.save();ctx.strokeStyle='#85abb577';ctx.setLineDash([6,5]);ctx.beginPath();ctx.arc(c.x,c.y,c.meteo===1?240:360,0,Math.PI*2);ctx.stroke();ctx.restore();}}}
function previewMeteo(id){let c=S.cities[id];meteoPreview={id,radius:stationQuote(c).radius};closeModal();openCity(id);toast('气象站覆盖预览 · 再点气象站可确认建设');}
function stationQuote(c){return {price:c.meteo?3200:2600,radius:c.meteo?360:240};}
function buildMeteo(id){let c=S.cities[id],q=c&&stationQuote(c);if(!c||c.kind==='bridgehead'||c.dormant||c.meteo>=2||S.points<q.price)return toast('城市未接入、已满级或资金不足');openModal(`<h2>${escapeHTML(c.name)} · 气象站</h2><p>费用 ¥${q.price} · 覆盖半径${q.radius}。范围内天气减速损失减半，重叠不叠加；台风航空停运不能抵消。确认后永久生效。</p><button class="secondary" onclick="previewMeteo(${id})">地图预览覆盖范围</button><button class="primary" onclick="confirmMeteo(${id})">确认建设</button><button onclick="closeModal()">取消</button>`);selected={type:'city',id};}
function confirmMeteo(id){let c=S.cities[id],q=stationQuote(c);if(c.meteo>=2||S.points<q.price)return;spend(q.price,'construction','气象站建设');c.meteo=(c.meteo||0)+1;meteoPreview=null;save();closeModal();openCity(id);}
function buildHub(id){let c=S.cities[id],price=3500+S.hubCount*1500;if(!c||c.kind==='bridgehead'||c.dormant||c.hub||S.hubCount>=hubLimit()||S.points<price)return toast('枢纽名额已满、城市未接入或资金不足');openModal(`<h2>建设交通枢纽</h2><p>${escapeHTML(c.name)} · ¥${price}。全图最多${hubLimit()}座，当前${S.hubCount}/${hubLimit()}。候车容量翻倍，换乘耗时降低30%，接近枢纽80地图单位内进站提速15%。</p><button class="primary" onclick="confirmHub(${id})">确认建设</button><button onclick="closeModal()">取消</button>`);}
function confirmHub(id){let c=S.cities[id],price=3500+S.hubCount*1500;if(!c||c.hub||S.hubCount>=hubLimit()||S.points<price)return;spend(price,'construction','建设交通枢纽');c.hub=true;S.hubCount++;save();closeModal();openCity(id);}
function showEngineering(){openModal(`<div class="modal-head"><div><span class="eyebrow">ENGINEERING / 0.4</span><h2>工程采购与天气</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="tabs"><button onclick="beginBridge('bus')">拉建公路桥</button><button onclick="beginBridge('track')">拉建铁路桥</button><button onclick="showWeather()">区域天气</button></div><p>桥头由你确定。公路桥1500起、铁路桥2600起；桥只付一次建设费。道路与桥面升级均有施工期，速度暂降30%。</p><h3>已有桥梁 · 拓宽 / 拆除</h3>${S.bridges.filter(x=>x.status!=='removed').map(x=>`<div class="quote-row"><span>${x.type==='bus'?'公路桥':'铁路桥'} #${x.id} · ${x.status==='open'?'正常':'待拆除'} · 桥面${x.level}级</span><button onclick="closeModal();openBridge(${x.id})">管理桥梁</button></div>`).join('')||'<p>还没有桥梁，选择上方建桥后在两岸拖动。</p>'}<h3>道路升级 / 铁路改造</h3><div class="tabs">${S.lines.filter(l=>l.type!=='air').map(l=>`<button onclick="openInfrastructure(${l.id})">${escapeHTML(l.name)}</button>`).join('')||'<small>先建立一条交通线路。</small>'}</div><h3>气象站与交通枢纽（${S.hubCount}/${hubLimit()}）</h3><div class="task-cities">${realCities().filter(c=>!c.dormant).map(c=>`<section><b>${escapeHTML(c.name)}</b><p>气象站 ${c.meteo||0}/2级 · ${c.hub?'已建枢纽':'普通站'}</p><button onclick="buildMeteo(${c.id})" ${c.meteo>=2||S.points<stationQuote(c).price?'disabled':''}>${c.meteo?'升级':'建'}气象站 ¥${stationQuote(c).price}</button><button onclick="buildHub(${c.id})" ${c.hub||S.hubCount>=hubLimit()||S.points<3500+S.hubCount*1500?'disabled':''}>枢纽 ¥${3500+S.hubCount*1500}</button></section>`).join('')}</div><h3>断线与维修</h3>${Object.entries(S.blockages).filter(([k,b])=>b.cause!=='demolish').map(([k,b])=>{let ids=k.split('-').slice(-2).map(Number),q=repairQuote(k);return `<div class="quote-row"><span>${escapeHTML(S.cities[ids[0]].name)}—${escapeHTML(S.cities[ids[1]].name)} · ${b.status==='pending'?'车辆清空中':b.status==='repairing'?'维修中':'已断线'}</span><button onclick="repairRoad('${k}')" ${b.status!=='broken'||S.points<q.price?'disabled':''}>维修 ¥${q.price} · ${q.days}天</button></div>`;}).join('')||'<p>暂无受损路段。</p>'}`);}
function showWeather(){openModal(`<div class="modal-head"><h2>区域天气与预报</h2><button class="close" onclick="showEngineering()">×</button></div>${S.climate.events.map(e=>`<div class="infra-card"><b>${{fog:'雾天',rain:'雨天',typhoon:'台风'}[e.type]} ${e.strong?'强':''}</b><p>第${Math.floor(e.start)+1}天至第${Math.floor(e.end)+1}天 · ${S.day<e.start?'预报':'影响中'}<br>范围在地图标出。公交受雾雨影响较大，铁路影响较小；强台风区域机场暂停新航班。</p></div>`).join('')||'<p>目前天气平稳，后续预报将提前显示。</p>'}<p>气象站范围内，天气造成的减速损失减半。夏秋中后期可能出现移动台风；地震仅在第150天后、高铁开放且接入6城后有低概率出现。</p><button class="secondary" onclick="closeModal()">回地图查看范围</button>`);}
const details02=showDetails;showDetails=function(rebuild=true){if(selected?.type==='bridge'){openBridge(selected.id);return;}if(selected&&(selected.type==='city'||selected.type==='stop')&&S.cities[selected.id]?.kind==='bridgehead'){openBridge(S.cities[selected.id].bridge);return;}details02(rebuild);if(selected?.type==='line'){let l=S.lines.find(x=>x.id===selected.id);if(!l)return;let el=$('details');if(!el.innerHTML.includes('class="service-list"')){el.innerHTML+=`<div class="service-list"><b>车辆运行控制</b>${S.vehicles.filter(v=>v.line===l.id).map(v=>`<div class="quote-row"><span>#${v.id} · ${v.pendingService?'交接中':v.service?.mode==='interval'?'区间车':v.service?.mode==='express'?'快车':'全程'}${v.parked?' · 暂停在安全端':''}</span><button onclick="setService(${v.id})">设置方案</button></div>`).join('')}</div>`;}if(!el.innerHTML.includes('部分路段停止接入')&&l.stops.some((id,i)=>i&&S.blockages[key(S.cities[l.stops[i-1]],S.cities[id],l.type)]))el.innerHTML+='<p class="danger">部分路段停止接入，两侧车辆分段运行。可在工程采购中维修，或重新接桥改线。</p>';}else if(selected?.type==='city'&&!$('details').innerHTML.includes('buildMeteo(')){let c=S.cities[selected.id];$('details').innerHTML+=`<div class="detail-actions"><button onclick="buildMeteo(${c.id})">气象站 ${c.meteo||0}/2</button><button onclick="buildHub(${c.id})">交通枢纽 ${S.hubCount}/${hubLimit()}</button></div>`;}};
const shop02=shop;shop=function(){shop02();$('modal-content').innerHTML=$('modal-content').innerHTML.replace('TRANSPORT DEPOT / 0.2','TRANSPORT DEPOT / 0.4').replace('桥隧在建线时计价','桥梁独立建造，隧道在建线时计价');$('modal-content').innerHTML+='<button class="secondary" onclick="showEngineering()">桥面 / 道路升级 / 气象站 / 交通枢纽 →</button>';};
lineStyle=function(l,alpha=1){ctx.globalAlpha=alpha;ctx.strokeStyle=l.color;ctx.lineWidth=l.type==='rail'?7:l.type==='emu'?4.5:l.type==='air'?2.8:3.7;ctx.setLineDash(l.type==='air'?[13,8]:[]);ctx.lineCap='round';ctx.lineJoin='round';};
const segment03=drawSegment;drawSegment=function(a,b,l){if(S.blockages[key(a,b,l.type)]?.status==='broken'||S.blockages[key(a,b,l.type)]?.status==='repairing')return;if(l.type==='emu'){strokeLaneRange(a,b,l);ctx.stroke();ctx.save();ctx.strokeStyle='#516c6b';ctx.lineWidth=7;ctx.setLineDash([1.3,10]);ctx.stroke();ctx.restore();}else segment03(a,b,l);};
const ui02=updateUI;updateUI=function(){ui02();$('route-list').querySelectorAll?.('[data-line]').forEach(el=>{let l=S.lines.find(x=>x.id===+el.dataset.line);if(l?.type==='emu'){let sw=el.querySelector('.swatch');sw.style.borderTopStyle='dashed';sw.style.borderTopWidth='3px';} });let pending=Object.values(S.blockages).filter(b=>b.status==='pending').length;if(pending)$('notice').textContent='受损 / 待拆路段已停止新车进入，原有车辆驶离后断开';else{let active=S.climate.events.filter(e=>S.day>=e.start&&S.day<e.end);if(active.length)$('notice').textContent='区域'+active.map(e=>({rain:'雨',fog:'雾',typhoon:'台风'}[e.type])).join('、')+'影响运行 · 气象站范围内延误减轻';}};
const welcome02=welcome;welcome=function(hasSave){welcome02(hasSave);$('modal-content').innerHTML=$('modal-content').innerHTML.replaceAll('0.2','0.4').replace('0.1存档仍保留','0.2存档仍保留').replace('运营中心可筹办商演、接合同；线路详情可升级道路。','工程采购可拉建桥梁、拓宽桥面、建气象站和限量枢纽；线路详情可设置区间车与快车。');};
const help02=help;help=function(){help02();$('modal-content').innerHTML=$('modal-content').innerHTML.replace('0.2 测试手册','0.4 测试手册')+`<div class="infra-card"><b>0.4 · 桥梁、天气与车辆方案</b><p>工程采购选择桥梁类型，在一岸拖向对岸，确认购买。线路可手动连桥头，或跨河拉线自动接入可用桥。点击桥管理拓宽与拆除；拆除让已进桥车辆正常驶离，再断线。区间车与快车在线路详情设置，下一座城市交接。气象站覆盖240/360范围；枢纽全图最多3座。高铁开放后出现远方城市，⌖可缩放全图。</p></div>`;};
// Typhoon season: 360-day calendar, July 26 (205) through September 30 (269).
const TYPHOON_SEASON={start:205,end:270};
function hasWeatherStation(){return realCities().some(c=>c.meteo>0);}
function typhoonPoint(e,t){if(!e.arc)return {x:e.x+(e.vx||0)*(e.end-e.start)*t,y:e.y+(e.vy||0)*(e.end-e.start)*t};let a=e.arc.from+(e.arc.to-e.arc.from)*Math.max(0,Math.min(1,t));return {x:e.arc.cx+Math.cos(a)*e.arc.radius,y:e.arc.cy+Math.sin(a)*e.arc.radius};}
weatherCenter=function(e){return e.type==='typhoon'&&e.arc?typhoonPoint(e,(S.day-e.start)/(e.end-e.start)):{x:e.x+(e.vx||0)*Math.max(0,S.day-e.start),y:e.y+(e.vy||0)*Math.max(0,S.day-e.start)};};
function ensureTyphoonSeason(year){let cl=S.climate;cl.seasons??={};if(cl.typhoonVersion!==1){cl.events=cl.events.filter(e=>e.type!=='typhoon');cl.typhoonVersion=1;}if(cl.seasons[year])return;let count=Math.random()<.5?3:4,span=(TYPHOON_SEASON.end-TYPHOON_SEASON.start)/count,events=[];for(let i=0;i<count;i++){let start=year*360+TYPHOON_SEASON.start+i*span+rand(0,Math.max(1,span-9)),duration=rand(6,8);events.push({id:'typhoon-'+year+'-'+i,type:'typhoon',strong:true,start,end:Math.min(year*360+TYPHOON_SEASON.end,start+duration),radius:rand(160,205),arc:{cx:rand(1280,1370),cy:440,radius:rand(550,600),from:2.2,to:4.2}});}cl.seasons[year]={count,starts:events.map(e=>e.start)};cl.events.push(...events.filter(e=>e.end>S.day));}
function visibleTyphoons(){let lead=hasWeatherStation()?2:0;return S.climate.events.filter(e=>e.type==='typhoon'&&S.day>=e.start-lead&&S.day<e.end);}
function flightHeld(a,b){return S.climate.events.some(e=>{if(e.type!=='typhoon'||S.day<e.start||S.day>=e.end)return false;return segDist(weatherCenter(e),a,b)<e.radius+25;});}
const canEnterBeforeStorm=canEnter;canEnter=function(a,b,type,v=null){if(type==='air'&&flightHeld(a,b)&&!(v&&v.t>0))return false;return canEnterBeforeStorm(a,b,type,v);};
updateClimate=function(oldDay){let cl=S.climate;ensureTyphoonSeason(Math.floor(S.day/360));if(S.day>=cl.next){let cs=realCities().filter(c=>!c.dormant),city=cs[Math.floor(Math.random()*cs.length)]||S.cities[0];cl.events.push({id:'weather-'+Math.floor(S.day),type:Math.random()<.5?'fog':'rain',strong:Math.random()<.4,start:S.day+2,end:S.day+6,x:city.x+rand(-80,80),y:city.y+rand(-60,60),radius:rand(170,260),vx:0,vy:0});cl.next=S.day+rand(11,18);toast('雾雨预报已更新 · 工程 / 天气中查看');}cl.events=cl.events.filter(e=>e.end>S.day);if(Math.floor(S.day)>oldDay&&S.day>=150&&S.unlocked.includes('rail')&&S.day-cl.lastQuake>=80&&realCities().filter(c=>!c.dormant).length>=6&&Math.random()<.008)triggerQuake();};
const climateWithoutTyphoons=drawClimate;drawClimate=function(){let all=S.climate.events;S.climate.events=all.filter(e=>e.type!=='typhoon');try{climateWithoutTyphoons();}finally{S.climate.events=all;}let station=hasWeatherStation();for(let e of visibleTyphoons()){let p=weatherCenter(e),forecast=S.day<e.start;ctx.save();if(station){ctx.strokeStyle='#799aa66b';ctx.lineWidth=1.1/Math.max(.5,view.scale);ctx.setLineDash([5/view.scale,7/view.scale]);ctx.beginPath();for(let i=0;i<=48;i++){let q=typhoonPoint(e,i/48);if(i)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);}ctx.stroke();ctx.strokeStyle='#7d9ca45c';ctx.lineWidth=1/view.scale;ctx.setLineDash([3/view.scale,6/view.scale]);ctx.beginPath();ctx.arc(p.x,p.y,e.radius,0,Math.PI*2);ctx.stroke();}if(!forecast){ctx.setLineDash([]);ctx.translate(p.x,p.y);let r=9/Math.max(.6,view.scale);ctx.strokeStyle='#718f9a';ctx.lineWidth=2/Math.max(.6,view.scale);for(let i=0;i<2;i++){ctx.beginPath();ctx.arc(0,0,r,i*Math.PI+.3,i*Math.PI+2.6);ctx.stroke();}ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(0,0,r*.3,0,Math.PI*2);ctx.fill();text('台风',0,r+12/view.scale,9/view.scale,'#6f8995');}else if(station)text('台风预报',p.x,p.y,10,'#78939b');ctx.restore();}};
showWeather=function(){let station=hasWeatherStation(),events=S.climate.events.filter(e=>e.type!=='typhoon'||visibleTyphoons().includes(e));openModal(`<div class="modal-head"><h2>区域天气与预报</h2><button class="close" onclick="showEngineering()">×</button></div>${events.map(e=>`<div class="infra-card"><b>${{fog:'雾天',rain:'雨天',typhoon:'台风'}[e.type]} ${e.strong?'强':''}</b><p>第${Math.floor(e.start)+1}天至第${Math.floor(e.end)+1}天 · ${S.day<e.start?'预报':'影响中'}<br>${e.type==='typhoon'?(station?'气象站已提供南→北圆弧路径和影响边界，地图只显示细线，不覆盖地形。':'未建气象站：地图只显示当前台风标识，路径与影响边界不可见。')+'受影响航段暂停新起飞，其他交通工具减速；离开后自动恢复。':'公交受雾雨影响较大，铁路影响较小。'}</p></div>`).join('')||'<p>目前没有可见天气事件。</p>'}<p>台风仅在每年7月底至9月底，约3—4次，沿南→北圆弧移动。气象站缓解地面交通减速，但不能解除台风停飞。已起飞航班先完成当前航段，再按天气安排后续起飞。</p><button class="secondary" onclick="closeModal()">返回地图</button>`);};
let routeGhosts=[];
function changedEdges(before,after){let current=new Set(after.slice(1).map((b,i)=>[after[i],b].sort((a,b)=>a-b).join('-')));return before.slice(1).map((b,i)=>[before[i],b]).filter(([a,b])=>!current.has([a,b].sort((a,b)=>a-b).join('-')));}
function drawRouteGhosts(){let now=performance.now(),items=routeGhosts.filter(g=>now-g.at<6500);routeGhosts=items;if(draft?.original){let old=S.lines.find(l=>l.id===draft.original);if(old){let edges=changedEdges(old.stops,draft.stops);if(edges.length)items=[...items,{line:{...old},edges,removed:old.stops.filter(id=>!draft.stops.includes(id)),at:now,preview:true}];}}for(let g of items){ctx.save();ctx.globalAlpha=g.preview?.38:.35*Math.max(0,1-(now-g.at)/6500);ctx.strokeStyle='#8e9d9b';ctx.lineWidth=2.5/Math.max(.6,view.scale);ctx.setLineDash([5/view.scale,6/view.scale]);for(let [a,b] of g.edges){if(S.cities[a]&&S.cities[b]){let ca=S.cities[a],cb=S.cities[b],dx=cb.x-ca.x,dy=cb.y-ca.y,len=Math.hypot(dx,dy)||1;ctx.save();ctx.translate(-dy/len*5/view.scale,dx/len*5/view.scale);strokeLaneRange(ca,cb,g.line);ctx.stroke();ctx.restore();}}for(let id of g.removed){let c=S.cities[id];if(!c||c.kind==='bridgehead')continue;ctx.beginPath();ctx.arc(c.x,c.y,radius(c)+9,0,Math.PI*2);ctx.stroke();text('原停靠',c.x,c.y-radius(c)-15,8,'#8c9996');}ctx.restore();}}
const commitBeforeGhost=commitDraft;commitDraft=function(skip=false){let old=draft?.original&&S.lines.find(l=>l.id===draft.original),before=old&&{...old,stops:[...old.stops]};commitBeforeGhost(skip);if(before&&!draft){let after=S.lines.find(l=>l.id===before.id);if(after){let edges=changedEdges(before.stops,after.stops);if(edges.length)routeGhosts.push({line:before,edges,removed:before.stops.filter(id=>!after.stops.includes(id)),at:performance.now()});}}};
const undoBeforeGhost=undoStopRemoval;undoStopRemoval=function(){undoBeforeGhost();routeGhosts=[];};

$('engineering').onclick=showEngineering;
const esc03=e=>{if(e.code==='Escape'&&bridgeDraft){bridgeDraft=null;engineeringPointer=null;$('drawbar').hidden=true;}};document.addEventListener('keydown',esc03);

/* Detail-sheet framing lives in ux.js (peek/expand sheet). */
/* View comfort: smooth "whole map" and soft pan limits (screen space, so it works rotated). */
function fitTarget(){let v={x:view.x,y:view.y,scale:view.scale};fit();let t={x:view.x,y:view.y,scale:view.scale};view.x=v.x;view.y=v.y;view.scale=v.scale;return t}
function animateView(t,ms=320){if(typeof requestAnimationFrame==='undefined'){Object.assign(view,t);return}let f={x:view.x,y:view.y,scale:view.scale},t0=performance.now();animateView.id=(animateView.id||0)+1;let id=animateView.id;animateView.activeId=id;(function step(n){if(id!==animateView.id)return;let p=Math.min(1,(n-t0)/ms),e=1-Math.pow(1-p,3);view.scale=f.scale+(t.scale-f.scale)*e;view.x=f.x+(t.x-f.x)*e;view.y=f.y+(t.y-f.y)*e;if(p<1)requestAnimationFrame(step);else animateView.activeId=null})(t0)}
function animateFit(){animateView(fitTarget())}
if(typeof document!=='undefined'&&document.getElementById?.('overview'))$('overview').onclick=animateFit;
function mapScreenBox(){let cs=S?.cities||[],xs=cs.map(c=>c.x),ys=cs.map(c=>c.y),x0=Math.min(0,...xs),x1=Math.max(1200,...xs),y0=Math.min(0,...ys),y1=Math.max(710,...ys),pts=[[x0,y0],[x1,y0],[x0,y1],[x1,y1]].map(([x,y])=>toScreen({x,y}));return{l:Math.min(...pts.map(p=>p.x)),r:Math.max(...pts.map(p=>p.x)),t:Math.min(...pts.map(p=>p.y)),b:Math.max(...pts.map(p=>p.y))}}
(function(){if(typeof requestAnimationFrame==='undefined'||!document.querySelector)return;
function tick(){try{if(S&&!modalOpen&&pointers.size===0){let band=fitBand(),m=mapScreenBox(),cy0=band.top+(band.bottom-band.top)*.45,cy1=band.bottom-(band.bottom-band.top)*.45;
 /* keep the map reaching the middle of the usable band */
 if(m.r<W*.45)view.x+=(W*.45-m.r)*.25;else if(m.l>W*.55)view.x+=(W*.55-m.l)*.25;
 if(m.b<cy0)view.y+=(cy0-m.b)*.25;else if(m.t>cy1)view.y+=(cy1-m.t)*.25;}}catch{}requestAnimationFrame(tick)}
requestAnimationFrame(tick)})();

// Discovered cities open after thirty simulation seconds, even without a route.
function cityHasRoute(c){return S.lines.some(l=>!l.retiring&&l.stops.includes(c.id));}
function initializeCityOpeningTimers(){for(let c of realCities())if(c.dormant&&!Number.isFinite(c.openingAt))c.openingAt=S.day+30/12;}
function cityOpeningRemaining(c){return c.dormant?Math.max(0,Math.ceil(((c.openingAt??S.day+2.5)-S.day)*12-1e-8)):0;}
function activateDiscoveredCity(c,automatic=false){if(!c.dormant||c.kind==='bridgehead')return;c.dormant=false;c.autoOpened=automatic;c.activatedDay=S.day;c.grace=0;c.warning=0;c.congestionPressure=0;let svc=cityService(c);svc.protectUntil=Math.max(svc.protectUntil,S.day+14);if(automatic)toast(c.name+'已开放 · 游客开始逐渐出现，请安排交通');}
function drawCityOpening(c){let remaining=cityOpeningRemaining(c),urgent=remaining<=10,r=radius(c)+14,pulse=urgent?.72+.28*Math.sin(S.day*12*3):.55;ctx.save();ctx.strokeStyle=urgent?'#c78139':'#a4b09a';ctx.lineWidth=(urgent?2.5:1.5)/Math.max(.6,view.scale);ctx.globalAlpha=pulse;ctx.beginPath();ctx.arc(c.x,c.y,r,-Math.PI/2,-Math.PI/2+Math.PI*2*Math.min(1,remaining/30));ctx.stroke();ctx.globalAlpha=1;let label=(urgent?'即将开放 · ':'开放倒计时 · ')+remaining+'s',y=c.y-96-c.size*9;roundBody(c.x-57,y-11,114,22,6,urgent?'#fff0d7':'#f5f6ec',urgent?'#d39c55':'#cbd5be',1);text(label,c.x,y+3,10,urgent?'#ac6529':'#7e8d73');ctx.restore();}
